// Geometry is deterministic and cached on resize, never regenerated by the wind.
export const smooth = (a, b, x) => { const n = Math.max(0, Math.min(1, (x-a)/(b-a))); return n*n*(3-2*n); };
function curve(u, v, height) {
  return height * (v + .22*Math.sin(u*7.5+v*.65) + .07*Math.sin(u*13.2-v*.6) + .045*Math.cos(u*4+v));
}
export function createTerrain(width, height, mobile = false) {
  if (!(width > 0 && height > 0)) return [];
  const budget = mobile ? 1600 : 4200;
  let spacing = Math.max(mobile ? 14 : 10.5, Math.sqrt(width*height*1.7/budget));
  const fieldHeight = mobile ? height*.64 : height;
  const top = mobile ? height*.36 : 0;
  for (;;) {
    const rows = Math.ceil(fieldHeight/(spacing*1.75));
    const points = [];
    // Arc-length resampling: a sloping curve gets more x samples, not wider dot gaps.
    for (let row=-6; row<=rows+6; row++) {
      const v = row/rows;
      let x = -spacing*2, y = top+curve(x/width,v,fieldHeight), remaining = spacing;
      const step = spacing/5;
      for (let nextX=x+step; nextX<=width+spacing*2; nextX+=step) {
        const nextY = top+curve(nextX/width,v,fieldHeight);
        let length = Math.hypot(nextX-x,nextY-y);
        while (length >= remaining) {
          const ratio = remaining/length;
          x += (nextX-x)*ratio; y += (nextY-y)*ratio;
          if (x>=0 && x<=width) {
            const u=x/width;
            points.push({x,y,u,v:y/height,row,spacing,radius:mobile?1.05:1.15,
              light:.5+.28*Math.cos(u*5.2+v*.7)+.16*Math.sin(u*9.1-v*1.1)});
          }
          length -= remaining; remaining=spacing;
        }
        remaining -= length; x=nextX; y=nextY;
      }
    }
    if (points.length<=budget) return points;
    spacing*=Math.max(1.08, Math.sqrt(points.length/budget));
  }
}
function packet(u, v, phase, start, width, strength) {
  const travel = (phase-start)*.105-.18;
  const bend = .065*Math.sin(v*4+u*2);
  const distance = (u-travel+bend)/width;
  return strength*Math.exp(-distance*distance)*smooth(start,start+1.5,phase)*(1-smooth(start+13,start+16,phase));
}
export function windAt(u, v, seconds) {
  const phase = ((seconds%38)+38)%38;
  const breeze = .065*Math.sin(u*8+v*4+seconds*.55)+.035*Math.cos(v*9-u*3+seconds*.32);
  return breeze+packet(u,v,phase,4,.14,.95)+packet(u,v,phase,8.2,.18,.78);
}
